-- Contracts generated by the system (template) + signing evidence. Additive only; existing file contracts keep working.
alter table public.contracts
  add column if not exists kind text not null default 'file',
  add column if not exists body text,
  add column if not exists terms jsonb,
  add column if not exists signed_ip text,
  add column if not exists signed_ua text;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'contracts_kind_check') then
    alter table public.contracts add constraint contracts_kind_check check (kind in ('file', 'template'));
  end if;
end $$;

-- a contract text is fixed once the customer can see it: only drafts may change their body/terms
create or replace function public.guard_contract_body()
returns trigger language plpgsql set search_path to 'public' as $function$
begin
  if old.status <> 'draft' and (new.body is distinct from old.body or new.terms is distinct from old.terms or new.kind is distinct from old.kind) then
    raise exception 'contract text is locked after sending';
  end if;
  return new;
end $function$;

do $$ begin
  if not exists (select 1 from pg_trigger where tgname = 'trg_guard_contract_body' and tgrelid = 'public.contracts'::regclass) then
    create trigger trg_guard_contract_body before update on public.contracts for each row execute function public.guard_contract_body();
  end if;
  -- admins may delete only drafts (never a contract the customer has seen)
  if not exists (select 1 from pg_policy where polname = 'ct_del' and polrelid = 'public.contracts'::regclass) then
    create policy ct_del on public.contracts for delete to authenticated using (public.is_admin() and status = 'draft');
  end if;
end $$;
